import { $generateHtmlFromNodes, $generateNodesFromDOM } from "@lexical/html";
import {
  $createLinkNode,
  AutoLinkNode,
  LinkNode,
  TOGGLE_LINK_COMMAND,
} from "@lexical/link";
import {
  INSERT_CHECK_LIST_COMMAND,
  INSERT_ORDERED_LIST_COMMAND,
  INSERT_UNORDERED_LIST_COMMAND,
  ListItemNode,
  ListNode,
} from "@lexical/list";
import {
  BOLD_ITALIC_STAR,
  BOLD_ITALIC_UNDERSCORE,
  BOLD_STAR,
  BOLD_UNDERSCORE,
  CHECK_LIST,
  HEADING,
  INLINE_CODE,
  ITALIC_STAR,
  ITALIC_UNDERSCORE,
  LINK as LINK_TRANSFORMER,
  ORDERED_LIST,
  QUOTE,
  STRIKETHROUGH,
  UNORDERED_LIST,
} from "@lexical/markdown";
import {
  AutoLinkPlugin,
  createLinkMatcherWithRegExp,
} from "@lexical/react/LexicalAutoLinkPlugin";
import { CheckListPlugin } from "@lexical/react/LexicalCheckListPlugin";
import { ClickableLinkPlugin } from "@lexical/react/LexicalClickableLinkPlugin";
import { LexicalComposer } from "@lexical/react/LexicalComposer";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { ContentEditable } from "@lexical/react/LexicalContentEditable";
import { LexicalErrorBoundary } from "@lexical/react/LexicalErrorBoundary";
import { HistoryPlugin } from "@lexical/react/LexicalHistoryPlugin";
import { LinkPlugin } from "@lexical/react/LexicalLinkPlugin";
import { ListPlugin } from "@lexical/react/LexicalListPlugin";
import { MarkdownShortcutPlugin } from "@lexical/react/LexicalMarkdownShortcutPlugin";
import { OnChangePlugin } from "@lexical/react/LexicalOnChangePlugin";
import { RichTextPlugin } from "@lexical/react/LexicalRichTextPlugin";
import { TabIndentationPlugin } from "@lexical/react/LexicalTabIndentationPlugin";
import {
  LexicalTypeaheadMenuPlugin,
  MenuOption,
  useBasicTypeaheadTriggerMatch,
} from "@lexical/react/LexicalTypeaheadMenuPlugin";
import { HeadingNode, QuoteNode } from "@lexical/rich-text";
import DOMPurify from "isomorphic-dompurify";
import {
  $createParagraphNode,
  $createTextNode,
  $getNearestNodeFromDOMNode,
  $getNodeByKey,
  $getRoot,
  $getSelection,
  $insertNodes,
  $isRangeSelection,
  $setSelection,
  COMMAND_PRIORITY_LOW,
  FORMAT_TEXT_COMMAND,
  KEY_MODIFIER_COMMAND,
  PASTE_COMMAND,
} from "lexical";
import {
  Bold,
  GripVertical,
  Italic,
  Link as LinkIcon,
  List,
  ListChecks,
  ListOrdered,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/thornberry/components/button";
import {
  RichTextButtonNode,
  RichTextButtonToolbarControl,
  RichTextButtons,
  checkButtonHref,
} from "@/registry/thornberry/components/rich-text-button";
import {
  RichTextImageNode,
  RichTextImageToolbarControls,
  RichTextImages,
  checkImageSrc,
  getRichTextImageSummary,
} from "@/registry/thornberry/components/rich-text-image";
import { Skeleton } from "@/registry/thornberry/components/skeleton";

import type {
  EditorState,
  EditorThemeClasses,
  Klass,
  LexicalEditor,
  LexicalNode,
  TextFormatType,
  TextNode,
} from "lexical";
import type {
  ComponentProps,
  DragEvent as ReactDragEvent,
  ReactNode,
  RefObject,
} from "react";
import type { RichTextButtonOptions } from "@/registry/thornberry/components/rich-text-button";
import type { RichTextImageOptions } from "@/registry/thornberry/components/rich-text-image";

/** Imperative handle exposed via `editorApi` for clearing/focusing the editor. */
export interface EditorApi {
  clearContent: () => void;
  focus: () => void;
}

/** Default node-class theme, mapped onto Sigil/Tailwind tokens. Override via the `theme` prop. */
const defaultTheme: EditorThemeClasses = {
  paragraph: "mb-2 last:mb-0",
  heading: {
    h1: "mt-4 mb-2 font-bold text-xl first:mt-0",
    h2: "mt-3 mb-2 font-bold text-lg first:mt-0",
    h3: "mt-3 mb-1 font-semibold text-base first:mt-0",
  },
  text: {
    bold: "font-semibold",
    italic: "italic",
    strikethrough: "line-through",
    underline: "underline",
    code: "rounded bg-muted px-1 py-0.5 font-mono text-[0.85em]",
  },
  list: {
    ul: "mb-2 ml-5 list-disc",
    ol: "mb-2 ml-5 list-decimal",
    listitem: "mb-1",
    // Checklist appearance only (glyph + color); the clickable geometry is
    // injected via CHECKLIST_ITEM_GEOMETRY so it can never be dropped.
    listitemUnchecked: "before:text-muted-foreground before:content-['○']",
    listitemChecked:
      "text-muted-foreground line-through before:text-primary before:content-['✓']",
  },
  link: "text-primary underline underline-offset-2 hover:opacity-80",
  quote: "my-2 border-border border-l-2 pl-3 text-muted-foreground italic",
};

/**
 * Geometry that makes a checklist item's checkbox clickable. Lexical's checkbox
 * is not a real `<input>`: `@lexical/list`'s `registerCheckList` toggles only
 * when a click lands in `[li.left, li.left + ::before width]`. So the `::before`
 * checkbox MUST sit at the list item's left edge, inside its box, with a real
 * width, or the visible checkmark and the clickable region never overlap and the
 * item can't be checked. Kept separate from appearance (glyph/color) and always
 * injected when `enableChecklist` is on, so a consumer theme only supplies
 * appearance and can never ship an unclickable checkbox.
 */
const CHECKLIST_ITEM_GEOMETRY =
  "relative list-none pl-6 before:absolute before:top-1 before:left-0 before:h-4 before:w-4 before:cursor-pointer before:text-center before:leading-4";

/**
 * Suppresses the marker on the structural `<li>` that only wraps a nested list.
 * When a list item is indented, Lexical wraps the sublist in a `<li>` and still
 * applies the list-item (and, in a checklist, the checked/unchecked) classes to
 * it, so that wrapper draws its own bullet/checkbox on top of the real nested
 * item's, a doubled marker. Removing the list marker and the checklist `::before`
 * glyph on the wrapper collapses it back to one. Injected centrally (like
 * CHECKLIST_ITEM_GEOMETRY) so a consumer theme can never reintroduce the double.
 */
const NESTED_LIST_ITEM_GEOMETRY = "list-none before:hidden after:hidden";

/**
 * Markdown shortcuts the editor understands as you type (e.g. `- ` for a
 * bullet, `1. ` for a numbered list, `# ` for a heading, `> ` for a quote,
 * `**bold**`, `` `code` ``). Code blocks are intentionally excluded (the
 * editor does not register a code-block node by default).
 */
const MARKDOWN_TRANSFORMERS = [
  HEADING,
  QUOTE,
  UNORDERED_LIST,
  ORDERED_LIST,
  CHECK_LIST,
  BOLD_ITALIC_STAR,
  BOLD_ITALIC_UNDERSCORE,
  BOLD_STAR,
  BOLD_UNDERSCORE,
  ITALIC_STAR,
  ITALIC_UNDERSCORE,
  STRIKETHROUGH,
  INLINE_CODE,
  LINK_TRANSFORMER,
];

// Matches absolute URLs (with scheme or a leading `www.`) so a bare link the
// user types or pastes becomes an anchor. Bare domains like `example.com` are
// intentionally left alone to avoid linkifying things like `file.txt`.
const URL_MATCHER =
  /((https?:\/\/(www\.)?)|(www\.))[-\w@:%.+~#=]{1,256}\.[a-z]{2,6}\b([-\w@:%+.~#?&/=]*)/i;
const EMAIL_MATCHER = /[\w.+-]+@([\w-]+\.)+[a-z]{2,}/i;

/**
 * AutoLink matchers turning bare URLs and email addresses into links as the
 * user types or pastes. Scheme-less URLs get an `https://` prefix; emails get a
 * `mailto:` scheme.
 */
const AUTO_LINK_MATCHERS = [
  createLinkMatcherWithRegExp(URL_MATCHER, (text) =>
    text.startsWith("http") ? text : `https://${text}`,
  ),
  createLinkMatcherWithRegExp(EMAIL_MATCHER, (text) => `mailto:${text}`),
];

/**
 * Normalize a pasted token into a link href, or null when it is not a single
 * URL/email. Drives "paste a URL over a selection to link it": only a lone
 * token (no whitespace) that reads as a URL or email becomes a link, so pasting
 * a sentence still replaces the selection as text.
 */
const linkFromText = (text: string): string | null => {
  const value = text.trim();
  if (!value || /\s/.test(value)) return null;
  if (/^https?:\/\/\S+$/i.test(value)) return value;
  if (/^www\.\S+$/i.test(value)) return `https://${value}`;
  if (/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(value)) return `mailto:${value}`;
  return null;
};

/** Read the editor's content as an HTML string. */
const exportToHtml = (editor: LexicalEditor): string => {
  let html = "";
  editor.getEditorState().read(() => {
    html = $generateHtmlFromNodes(editor);
  });
  return html;
};

/** Read the editor's plain-text content. */
const getTextContent = (editor: LexicalEditor): string => {
  let text = "";
  editor.getEditorState().read(() => {
    text = $getRoot().getTextContent();
  });
  return text;
};

/** Whether the editor holds only whitespace. */
const isEditorEmpty = (editor: LexicalEditor): boolean => {
  let empty = true;
  editor.getEditorState().read(() => {
    empty = $getRoot().getTextContent().trim().length === 0;
  });
  return empty;
};

/** Replace the editor's content with parsed HTML. */
const importFromHtml = (editor: LexicalEditor, html: string): void => {
  editor.update(() => {
    const dom = new DOMParser().parseFromString(html, "text/html");
    const nodes = $generateNodesFromDOM(editor, dom);
    const root = $getRoot();
    root.clear();
    $insertNodes(nodes);
    $setSelection(null);
  });
};

interface ToolbarButtonProps extends ComponentProps<typeof Button> {
  label: string;
}

/**
 * Toolbar button. Uses onMouseDown + preventDefault so clicking it does not
 * blur the editor and lose the current selection before the command runs.
 */
const ToolbarButton = ({
  label,
  children,
  className,
  ...rest
}: ToolbarButtonProps) => (
  <Button
    type="button"
    size="icon"
    variant="ghost"
    aria-label={label}
    title={label}
    className={cn("size-8", className)}
    onMouseDown={(event) => event.preventDefault()}
    {...rest}
  >
    {children}
  </Button>
);

/** Minimal formatting toolbar: bold, italic, lists, link, optional checklist, images, and buttons. */
const Toolbar = ({
  enableChecklist,
  enableImages,
  enableButtons,
  className,
}: {
  enableChecklist?: boolean;
  enableImages?: boolean;
  enableButtons?: boolean;
  className?: string;
}) => {
  const [editor] = useLexicalComposerContext();

  const format = (type: TextFormatType) =>
    editor.dispatchCommand(FORMAT_TEXT_COMMAND, type);

  const insertLink = () => {
    const url = window.prompt("Link URL");
    if (url) editor.dispatchCommand(TOGGLE_LINK_COMMAND, url.trim());
  };

  return (
    <div
      className={cn(
        "relative flex items-center gap-0.5 border-input border-b px-1 py-1",
        className,
      )}
    >
      <ToolbarButton label="Bold" onClick={() => format("bold")}>
        <Bold />
      </ToolbarButton>
      <ToolbarButton label="Italic" onClick={() => format("italic")}>
        <Italic />
      </ToolbarButton>
      <ToolbarButton
        label="Bulleted list"
        onClick={() =>
          editor.dispatchCommand(INSERT_UNORDERED_LIST_COMMAND, undefined)
        }
      >
        <List />
      </ToolbarButton>
      <ToolbarButton
        label="Numbered list"
        onClick={() =>
          editor.dispatchCommand(INSERT_ORDERED_LIST_COMMAND, undefined)
        }
      >
        <ListOrdered />
      </ToolbarButton>
      {enableChecklist && (
        <ToolbarButton
          label="Checklist"
          onClick={() =>
            editor.dispatchCommand(INSERT_CHECK_LIST_COMMAND, undefined)
          }
        >
          <ListChecks />
        </ToolbarButton>
      )}
      <ToolbarButton label="Link" onClick={insertLink}>
        <LinkIcon />
      </ToolbarButton>
      {enableImages && (
        <RichTextImageToolbarControls
          renderButton={({ label, icon, onClick, pressed }) => (
            <ToolbarButton
              key={label}
              label={label}
              aria-pressed={pressed}
              onClick={onClick}
            >
              {icon}
            </ToolbarButton>
          )}
        />
      )}
      {enableButtons && (
        <RichTextButtonToolbarControl
          renderButton={({ label, icon, onClick, pressed }) => (
            <ToolbarButton
              label={label}
              aria-pressed={pressed}
              aria-expanded={pressed}
              onClick={onClick}
            >
              {icon}
            </ToolbarButton>
          )}
        />
      )}
    </div>
  );
};

/** Keep Lexical's editable state in sync with the `editable` prop. */
const EditablePlugin = ({ editable }: { editable: boolean }) => {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    editor.setEditable(editable);
  }, [editor, editable]);

  return null;
};

// Offset of the drag handle from the editor surface's left edge; sits inside the
// gutter the surface reserves (pl-7) so the handle never overlaps the text.
const DRAG_HANDLE_GUTTER = 4;
// Horizontal inset of the drop line, matching the text gutter so it lines up
// with content rather than running under the handle.
const DROP_LINE_INSET = 24;

/**
 * The ordered draggable units inside the editor root: every top-level block,
 * except a list block contributes its direct list items instead, so checklist
 * and list rows reorder individually (Lexical's stock plugin only sees the whole
 * list). Nested sublists are left to drag with their parent item in this pass.
 */
const getDragUnits = (rootEl: HTMLElement): HTMLElement[] => {
  const units: HTMLElement[] = [];
  for (const child of Array.from(rootEl.children)) {
    if (!(child instanceof HTMLElement)) continue;
    if (child.tagName === "UL" || child.tagName === "OL") {
      for (const li of Array.from(child.children)) {
        if (li instanceof HTMLElement && li.tagName === "LI") units.push(li);
      }
    } else {
      units.push(child);
    }
  }
  return units;
};

/**
 * A draggable unit is either a list item or a top-level block. A unit only drops
 * among units of its own kind (item among items, block among blocks), so a move
 * can never put a list item at the document root or a block inside a list and
 * corrupt the tree.
 */
const dragUnitClass = (el: HTMLElement): "list-item" | "block" =>
  el.tagName === "LI" ? "list-item" : "block";

/** Which edge of a unit a drop lands on, from the pointer's y within it. */
const dropSide = (
  top: number,
  height: number,
  clientY: number,
): "before" | "after" => (clientY < top + height / 2 ? "before" : "after");

/**
 * Build a solid, opaque card clone of a block to use as the drag image, so the
 * drag shows the actual block content rather than the browser's faint native
 * snapshot of the live element. Appended off-screen (laid out so the browser can
 * snapshot it); the caller removes it once the drag has started.
 */
const buildBlockDragImage = (unit: HTMLElement): HTMLElement => {
  const rect = unit.getBoundingClientRect();
  const preview = unit.cloneNode(true) as HTMLElement;
  preview.setAttribute("data-block-drag-image", "");
  // keep the block's own prose classes, add card chrome (bg-background makes it
  // opaque, not the translucent native ghost)
  preview.className = cn(
    unit.className,
    "rounded-md border border-border bg-background px-3 py-2 text-sm shadow-lg",
  );
  Object.assign(preview.style, {
    position: "fixed",
    top: "-10000px",
    left: "-10000px",
    width: `${Math.round(rect.width)}px`,
    margin: "0",
    boxSizing: "border-box",
    pointerEvents: "none",
  });
  document.body.appendChild(preview);
  return preview;
};

/**
 * Hover drag handle for reordering editor content. Unlike Lexical's stock
 * draggable-block plugin (top-level blocks only), each list item is its own
 * draggable unit via {@link getDragUnits}, so checklist and list rows reorder
 * individually. Purpose-built so the handle and drop line fade and glide: show
 * and hide toggle only opacity, leaving transform free to transition between
 * units. A unit drops only among units of its own kind (see {@link dragUnitClass}).
 */
const BlockDragPlugin = ({ anchorElem }: { anchorElem: HTMLElement }) => {
  const [editor] = useLexicalComposerContext();
  const handleRef = useRef<HTMLDivElement>(null);
  const lineRef = useRef<HTMLDivElement>(null);
  // the unit the handle currently points at (the drag source once a drag starts)
  const hoveredUnitRef = useRef<HTMLElement | null>(null);
  const dragRef = useRef<{ key: string; kind: "list-item" | "block" } | null>(
    null,
  );
  const dropRef = useRef<{ key: string; side: "before" | "after" } | null>(
    null,
  );

  // Resolve the Lexical node key for a unit's DOM element (a top-level block
  // maps to its own node; a list item maps to its ListItemNode).
  const unitNodeKey = useCallback(
    (unit: HTMLElement): string => {
      let key = "";
      // editor.read (not getEditorState().read) sets the active editor context
      // $getNearestNodeFromDOMNode requires
      editor.read(() => {
        const node = $getNearestNodeFromDOMNode(unit);
        if (node) key = node.getKey();
      });
      return key;
    },
    [editor],
  );

  useEffect(() => {
    const rootEl = editor.getRootElement();
    if (!rootEl) return;

    const placeHandle = (unit: HTMLElement | null) => {
      const el = handleRef.current;
      if (!el) return;
      if (!unit) {
        el.style.opacity = "0";
        return;
      }
      const a = anchorElem.getBoundingClientRect();
      const u = unit.getBoundingClientRect();
      const top =
        u.top - a.top + (u.height - el.offsetHeight) / 2 + anchorElem.scrollTop;
      el.style.transform = `translate(${DRAG_HANDLE_GUTTER}px, ${Math.round(top)}px)`;
      el.style.opacity = "1";
    };

    const placeLine = (unit: HTMLElement, side: "before" | "after") => {
      const line = lineRef.current;
      if (!line) return;
      const a = anchorElem.getBoundingClientRect();
      const u = unit.getBoundingClientRect();
      const edge = side === "before" ? u.top : u.bottom;
      line.style.transform = `translate(${DROP_LINE_INSET}px, ${Math.round(edge - a.top + anchorElem.scrollTop)}px)`;
      line.style.width = `${Math.round(u.width)}px`;
      line.style.opacity = "1";
    };

    const hideLine = () => {
      if (lineRef.current) lineRef.current.style.opacity = "0";
    };

    const unitAtY = (clientY: number, kind?: "list-item" | "block") => {
      const units = kind
        ? getDragUnits(rootEl).filter((u) => dragUnitClass(u) === kind)
        : getDragUnits(rootEl);
      let nearest: HTMLElement | null = null;
      let nearestDist = Number.POSITIVE_INFINITY;
      for (const u of units) {
        const r = u.getBoundingClientRect();
        if (clientY >= r.top && clientY <= r.bottom) return u;
        const dist = clientY < r.top ? r.top - clientY : clientY - r.bottom;
        if (dist < nearestDist) {
          nearestDist = dist;
          nearest = u;
        }
      }
      return nearest;
    };

    const onMouseMove = (e: MouseEvent) => {
      if (dragRef.current) return;
      const unit = unitAtY(e.clientY);
      hoveredUnitRef.current = unit;
      placeHandle(unit);
    };
    const onMouseLeave = () => {
      if (dragRef.current) return;
      hoveredUnitRef.current = null;
      placeHandle(null);
    };
    const onDragOver = (e: DragEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      // allow the drop regardless of where it lands so onDrop always fires
      e.preventDefault();
      const unit = unitAtY(e.clientY, drag.kind);
      if (!unit) {
        dropRef.current = null;
        hideLine();
        return;
      }
      const r = unit.getBoundingClientRect();
      const side = dropSide(r.top, r.height, e.clientY);
      const key = unitNodeKey(unit);
      dropRef.current = key ? { key, side } : null;
      placeLine(unit, side);
    };
    const endDrag = () => {
      dragRef.current = null;
      dropRef.current = null;
      hideLine();
      placeHandle(null);
    };
    const onDrop = (e: DragEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      e.preventDefault();
      const drop = dropRef.current;
      if (drop && drop.key !== drag.key) {
        editor.update(() => {
          const dragged = $getNodeByKey(drag.key);
          const target = $getNodeByKey(drop.key);
          if (dragged && target && dragged !== target) {
            if (drop.side === "after") target.insertAfter(dragged);
            else target.insertBefore(dragged);
          }
        });
      }
      endDrag();
    };

    anchorElem.addEventListener("mousemove", onMouseMove);
    anchorElem.addEventListener("mouseleave", onMouseLeave);
    anchorElem.addEventListener("dragover", onDragOver);
    anchorElem.addEventListener("drop", onDrop);
    anchorElem.addEventListener("dragend", endDrag);
    return () => {
      anchorElem.removeEventListener("mousemove", onMouseMove);
      anchorElem.removeEventListener("mouseleave", onMouseLeave);
      anchorElem.removeEventListener("dragover", onDragOver);
      anchorElem.removeEventListener("drop", onDrop);
      anchorElem.removeEventListener("dragend", endDrag);
    };
  }, [editor, anchorElem, unitNodeKey]);

  const onHandleDragStart = (e: ReactDragEvent<HTMLDivElement>) => {
    const unit = hoveredUnitRef.current;
    const key = unit ? unitNodeKey(unit) : "";
    if (!unit || !key) {
      e.preventDefault();
      return;
    }
    dragRef.current = { key, kind: dragUnitClass(unit) };
    e.dataTransfer.effectAllowed = "move";
    // some browsers refuse to start a drag unless data is set
    e.dataTransfer.setData("text/plain", "");
    // Use a solid card clone as the drag image instead of the browser's faint
    // native snapshot of the live block, so the user sees the actual content as
    // a card (closer to the board's drag). The browser snapshots synchronously
    // at dragstart, so the off-screen clone can be removed on the next frame.
    const preview = buildBlockDragImage(unit);
    e.dataTransfer.setDragImage(preview, 12, 16);
    requestAnimationFrame(() => preview.remove());
  };

  return (
    <>
      <div
        ref={handleRef}
        draggable
        onDragStart={onHandleDragStart}
        data-block-drag-handle
        aria-label="Drag to reorder block"
        role="button"
        tabIndex={-1}
        className="hover:bg-muted absolute top-0 left-0 flex cursor-grab rounded-sm px-0.5 py-1 opacity-0 transition-all duration-150 ease-out will-change-transform active:cursor-grabbing"
      >
        <GripVertical className="text-muted-foreground size-4" />
      </div>
      <div
        ref={lineRef}
        className="bg-primary pointer-events-none absolute top-0 left-0 h-0.5 rounded-full opacity-0 transition-all duration-150 ease-out will-change-transform"
      />
    </>
  );
};

/**
 * Link affordances for selections: paste a URL over highlighted text to wrap it
 * in a link, and Cmd/Ctrl+K to link the selection (the keyboard equivalent of
 * the toolbar link button). Both no-op on a collapsed selection so normal paste
 * and other shortcuts are untouched.
 */
const LinkShortcutsPlugin = () => {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    const unregisterPaste = editor.registerCommand(
      PASTE_COMMAND,
      (event) => {
        const selection = $getSelection();
        if (!$isRangeSelection(selection) || selection.isCollapsed()) {
          return false;
        }
        // the paste payload may be a clipboard event or (for some input
        // methods) an input event carrying a dataTransfer
        const data =
          "clipboardData" in event
            ? event.clipboardData
            : "dataTransfer" in event
              ? event.dataTransfer
              : null;
        const href = linkFromText(data?.getData("text/plain") ?? "");
        if (!href) return false;
        event.preventDefault();
        editor.dispatchCommand(TOGGLE_LINK_COMMAND, href);
        return true;
      },
      COMMAND_PRIORITY_LOW,
    );

    const unregisterShortcut = editor.registerCommand<KeyboardEvent>(
      KEY_MODIFIER_COMMAND,
      (event) => {
        const isLinkShortcut =
          (event.metaKey || event.ctrlKey) &&
          !event.altKey &&
          event.key.toLowerCase() === "k";
        if (!isLinkShortcut) return false;

        const selection = $getSelection();
        if (!$isRangeSelection(selection) || selection.isCollapsed()) {
          return false;
        }
        event.preventDefault();
        const url = window.prompt("Link URL");
        if (url?.trim()) {
          editor.dispatchCommand(TOGGLE_LINK_COMMAND, url.trim());
        }
        return true;
      },
      COMMAND_PRIORITY_LOW,
    );

    return () => {
      unregisterPaste();
      unregisterShortcut();
    };
  }, [editor]);

  return null;
};

/** Seed initial HTML content and wire up the imperative `editorApi` handle. */
const EditorApiPlugin = ({
  editorApi,
  defaultContent,
}: {
  editorApi?: RefObject<EditorApi | null>;
  defaultContent?: string;
}) => {
  const [editor] = useLexicalComposerContext();
  const seeded = useRef(false);

  useEffect(() => {
    if (defaultContent && !seeded.current) {
      seeded.current = true;
      importFromHtml(editor, defaultContent);
    }
  }, [editor, defaultContent]);

  useEffect(() => {
    if (!editorApi) return;
    editorApi.current = {
      clearContent: () =>
        editor.update(() => {
          const root = $getRoot();
          root.clear();
          const paragraph = $createParagraphNode();
          root.append(paragraph);
          paragraph.select();
        }),
      focus: () =>
        editor.focus(() =>
          editor.update(() => {
            $getRoot().selectEnd();
          }),
        ),
    };
  }, [editor, editorApi]);

  return null;
};

/** A mentionable entity offered in the `@`-typeahead. */
export interface MentionItem {
  /** Stable id (e.g. user id). */
  id: string;
  /** Display label, shown after the `@` (no leading `@`). */
  label: string;
  /** Optional link target inserted for the mention. */
  url?: string;
}

class MentionTypeaheadOption extends MenuOption {
  item: MentionItem;

  constructor(item: MentionItem) {
    super(item.id);
    this.item = item;
  }
}

/**
 * `@`-mention typeahead. Filters the provided `items` by the typed query and
 * inserts the selected mention as a link (`@label` → `url`).
 */
const MentionTypeahead = ({ items }: { items: MentionItem[] }) => {
  const [editor] = useLexicalComposerContext();
  const [query, setQuery] = useState<string | null>(null);

  const triggerFn = useBasicTypeaheadTriggerMatch("@", { minLength: 0 });

  const options = useMemo(() => {
    const normalized = (query ?? "").toLowerCase();
    return items
      .filter((item) => item.label.toLowerCase().includes(normalized))
      .slice(0, 6)
      .map((item) => new MentionTypeaheadOption(item));
  }, [items, query]);

  const onSelectOption = useCallback(
    (
      option: MentionTypeaheadOption,
      nodeToReplace: TextNode | null,
      closeMenu: () => void,
    ) => {
      editor.update(() => {
        const mention = $createLinkNode(option.item.url ?? "#");
        mention.append($createTextNode(`@${option.item.label}`));
        if (nodeToReplace) nodeToReplace.replace(mention);
        const trailing = $createTextNode(" ");
        mention.insertAfter(trailing);
        trailing.select();
        closeMenu();
      });
    },
    [editor],
  );

  return (
    <LexicalTypeaheadMenuPlugin<MentionTypeaheadOption>
      onQueryChange={setQuery}
      onSelectOption={onSelectOption}
      triggerFn={triggerFn}
      options={options}
      menuRenderFn={(
        anchorRef,
        { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex },
      ) =>
        anchorRef.current && options.length
          ? createPortal(
              <ul className="bg-popover text-popover-foreground z-50 max-h-56 min-w-44 overflow-auto rounded-md border p-1 shadow-md">
                {options.map((option, index) => (
                  <li
                    key={option.key}
                    className={cn(
                      "cursor-pointer rounded-sm px-2 py-1.5 text-sm",
                      selectedIndex === index && "bg-muted",
                    )}
                    onMouseEnter={() => setHighlightedIndex(index)}
                    onMouseDown={(event) => {
                      event.preventDefault();
                      selectOptionAndCleanUp(option);
                    }}
                  >
                    @{option.item.label}
                  </li>
                ))}
              </ul>,
              anchorRef.current,
            )
          : null
      }
    />
  );
};

/** An item offered in the `#`-reference typeahead (e.g. an issue/post). */
export interface IssueReferenceItem {
  /** Stable id (e.g. post rowId). */
  id: string;
  /** Numeric reference inserted after `#` (e.g. an issue number). */
  number: number;
  /** Title, shown in the menu. */
  title: string;
}

class IssueReferenceOption extends MenuOption {
  item: IssueReferenceItem;

  constructor(item: IssueReferenceItem) {
    super(String(item.id));
    this.item = item;
  }
}

/**
 * `#`-reference typeahead. Filters the provided `items` by the typed number or
 * title and inserts the selected reference as plain `#<number>` text (GitHub
 * `#123` style). Consumers linkify the inserted reference when rendering.
 */
const IssueReferenceTypeahead = ({
  items,
}: {
  items: IssueReferenceItem[];
}) => {
  const [editor] = useLexicalComposerContext();
  const [query, setQuery] = useState<string | null>(null);

  const triggerFn = useBasicTypeaheadTriggerMatch("#", { minLength: 0 });

  const options = useMemo(() => {
    const normalized = (query ?? "").toLowerCase();
    return items
      .filter(
        (item) =>
          String(item.number).startsWith(normalized) ||
          item.title.toLowerCase().includes(normalized),
      )
      .slice(0, 6)
      .map((item) => new IssueReferenceOption(item));
  }, [items, query]);

  const onSelectOption = useCallback(
    (
      option: IssueReferenceOption,
      nodeToReplace: TextNode | null,
      closeMenu: () => void,
    ) => {
      editor.update(() => {
        const reference = $createTextNode(`#${option.item.number}`);
        if (nodeToReplace) nodeToReplace.replace(reference);
        const trailing = $createTextNode(" ");
        reference.insertAfter(trailing);
        trailing.select();
        closeMenu();
      });
    },
    [editor],
  );

  return (
    <LexicalTypeaheadMenuPlugin<IssueReferenceOption>
      onQueryChange={setQuery}
      onSelectOption={onSelectOption}
      triggerFn={triggerFn}
      options={options}
      menuRenderFn={(
        anchorRef,
        { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex },
      ) =>
        anchorRef.current && options.length
          ? createPortal(
              <ul className="bg-popover text-popover-foreground z-50 max-h-56 max-w-72 min-w-56 overflow-auto rounded-md border p-1 shadow-md">
                {options.map((option, index) => (
                  <li
                    key={option.key}
                    className={cn(
                      "flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm",
                      selectedIndex === index && "bg-muted",
                    )}
                    onMouseEnter={() => setHighlightedIndex(index)}
                    onMouseDown={(event) => {
                      event.preventDefault();
                      selectOptionAndCleanUp(option);
                    }}
                  >
                    <span className="text-muted-foreground shrink-0 font-medium">
                      #{option.item.number}
                    </span>
                    <span className="truncate">{option.item.title}</span>
                  </li>
                ))}
              </ul>,
              anchorRef.current,
            )
          : null
      }
    />
  );
};

/** What `onUpdate` reports on every change. */
interface RichTextEditorUpdate {
  /** Read the content as HTML. */
  getHTML: () => string;
  /** Read the content as plain text. */
  getText: () => string;
  /** Whether the editor holds no text (and, with `images`, no images). */
  isEmpty: boolean;
  /**
   * Whether any image lacks alt text. Always false without `images`. Block
   * publishing while true.
   */
  hasMissingAltText: boolean;
  /**
   * Whether any image is still uploading (its placeholder exports nothing).
   * Always false without `images`. Block publishing while true.
   */
  isUploading: boolean;
  /**
   * Whether any loaded or pasted image is hosted elsewhere (refused by
   * `images.isAllowedSrc`, or plain http) and waits for an uploaded copy; it
   * exports nothing until then. Always false without `images`. Warn or block
   * publishing while true.
   */
  hasExternalImages: boolean;
}

interface RichTextEditorProps
  extends Omit<ComponentProps<"div">, "placeholder" | "onChange"> {
  /** Imperative handle for clearing/focusing the editor. */
  editorApi?: RefObject<EditorApi | null>;
  /** Called on every change with the current HTML/text and empty state. */
  onUpdate?: (update: RichTextEditorUpdate) => void;
  /** Initial HTML content. */
  defaultContent?: string;
  /** Whether the editor accepts input. */
  editable?: boolean;
  /** Placeholder shown when empty. */
  placeholder?: string;
  /** Hide the formatting toolbar. */
  hideToolbar?: boolean;
  /** Class applied to the formatting toolbar (e.g. to tint its background). */
  toolbarClassName?: string;
  /** When provided, enables an `@`-mention typeahead over these items. */
  mentionItems?: MentionItem[];
  /** When provided, enables a `#`-issue-reference typeahead over these items. */
  issueReferenceItems?: IssueReferenceItem[];
  /** Show a checklist (task list) button in the toolbar and enable the plugin. */
  enableChecklist?: boolean;
  /**
   * Enable a hover drag handle for reordering top-level blocks (Notion-style).
   * Off by default: it reserves a left gutter on the editor surface, which is
   * unwanted on single-line surfaces (titles, list items). Turn on for rich,
   * multi-block editors (e.g. a task description).
   */
  enableBlockDrag?: boolean;
  /**
   * Turn on images: a toolbar upload button, "insert from link" (https only),
   * paste, and drag-and-drop. Each image needs alt text, and exports as
   * email-safe markup with an absolute URL and a pixel width. Off when omitted
   * (and may be turned on or off after mount).
   */
  images?: RichTextImageOptions;
  /**
   * Turn on call-to-action buttons: an "Insert button" toolbar control that
   * takes a label and an `https://` or `mailto:` link. Each button is a block
   * of its own and exports as
   * `<p><a href="…" data-variant="button">Label</a></p>` for the consumer to
   * style. Off when omitted (and may be turned on or off after mount)
   */
  buttons?: RichTextButtonOptions;
  /** Extra Lexical node classes to register (e.g. an app's image node). */
  extraNodes?: ReadonlyArray<Klass<LexicalNode>>;
  /** Extra Lexical plugins rendered inside the composer (e.g. image paste, code highlighting). */
  plugins?: ReactNode;
  /** Override the node-class theme (e.g. to match an app's prose styling). */
  theme?: EditorThemeClasses;
  /** Class applied to the loading skeleton. */
  skeletonClassName?: string;
  /** Class applied to the editor surface. */
  editorClassName?: string;
}

/**
 * Friendly rich-text editor built on Lexical: bold, italic, lists, and links
 * via a minimal toolbar. Content is read out as sanitizable HTML through
 * `onUpdate`. Render stored HTML back with {@link RichTextContent}.
 */
const RichTextEditor = ({
  editorApi,
  onUpdate,
  defaultContent,
  editable = true,
  placeholder,
  hideToolbar = false,
  toolbarClassName,
  mentionItems,
  issueReferenceItems,
  enableChecklist,
  enableBlockDrag,
  images,
  buttons,
  extraNodes,
  plugins,
  theme,
  skeletonClassName,
  className,
  editorClassName,
  ...rest
}: RichTextEditorProps) => {
  const [mounted, setMounted] = useState(false);
  const [isEmpty, setIsEmpty] = useState(!defaultContent);
  // The drag plugin needs a positioned DOM anchor to portal the handle into;
  // capture the surface wrapper once it mounts (keep the last non-null node, as
  // the Lexical playground does, so the plugin never loses its anchor).
  const [anchorElem, setAnchorElem] = useState<HTMLDivElement | null>(null);
  const onAnchorRef = useCallback((el: HTMLDivElement | null) => {
    if (el !== null) {
      setAnchorElem(el);
    }
  }, []);
  const blockDragEnabled = Boolean(enableBlockDrag) && editable;

  // Lexical touches the DOM, so only render it on the client to stay SSR-safe.
  useEffect(() => setMounted(true), []);

  if (!mounted) {
    return (
      <Skeleton
        className={cn("h-24 w-full rounded-md", skeletonClassName ?? className)}
        {...rest}
      />
    );
  }

  const baseTheme = theme ?? defaultTheme;
  // Always suppress the nested-wrapper marker (see NESTED_LIST_ITEM_GEOMETRY) so
  // indenting any list, bulleted, numbered, or checklist, never doubles the
  // marker, and always pair the checklist appearance with CHECKLIST_ITEM_GEOMETRY
  // so the checkbox is clickable regardless of the consumer's theme, falling back
  // to the default glyphs when a custom theme omits checklist styling.
  const editorTheme = {
    ...baseTheme,
    list: {
      ...baseTheme.list,
      nested: {
        ...baseTheme.list?.nested,
        listitem: cn(
          NESTED_LIST_ITEM_GEOMETRY,
          baseTheme.list?.nested?.listitem,
        ),
      },
      ...(enableChecklist
        ? {
            listitemUnchecked: cn(
              CHECKLIST_ITEM_GEOMETRY,
              baseTheme.list?.listitemUnchecked ??
                defaultTheme.list?.listitemUnchecked,
            ),
            listitemChecked: cn(
              CHECKLIST_ITEM_GEOMETRY,
              baseTheme.list?.listitemChecked ??
                defaultTheme.list?.listitemChecked,
            ),
          }
        : {}),
    },
  };

  const initialConfig = {
    namespace: "RichTextEditor",
    theme: editorTheme,
    editable,
    onError: (error: Error) => console.error("Lexical error:", error),
    nodes: [
      HeadingNode,
      QuoteNode,
      ListNode,
      ListItemNode,
      LinkNode,
      AutoLinkNode,
      // always registered so `images` can be toggled after mount; it stays
      // inert (no import, no toolbar, no paste handling) while `images` is off
      RichTextImageNode,
      // likewise always registered, and inert while `buttons` is off
      RichTextButtonNode,
      ...(extraNodes ?? []),
    ],
  };

  const handleChange = (_state: EditorState, editor: LexicalEditor) => {
    const imageSummary = images ? getRichTextImageSummary(editor) : null;
    const empty = isEditorEmpty(editor) && !imageSummary?.count;
    setIsEmpty(empty);
    onUpdate?.({
      getHTML: () => exportToHtml(editor),
      getText: () => getTextContent(editor),
      isEmpty: empty,
      hasMissingAltText: imageSummary?.hasMissingAltText ?? false,
      isUploading: imageSummary?.isUploading ?? false,
      hasExternalImages: imageSummary?.hasExternalImages ?? false,
    });
  };

  return (
    <div
      className={cn(
        "rounded-md border border-input bg-background text-sm focus-within:ring-1 focus-within:ring-ring",
        className,
      )}
      data-rich-text-editor=""
      {...rest}
    >
      <LexicalComposer initialConfig={initialConfig}>
        <RichTextImages options={images}>
          <RichTextButtons options={buttons}>
            {!hideToolbar && editable && (
              <Toolbar
                enableChecklist={enableChecklist}
                enableImages={Boolean(images)}
                enableButtons={Boolean(buttons)}
                className={toolbarClassName}
              />
            )}

            <div className="relative" ref={onAnchorRef}>
              <RichTextPlugin
                contentEditable={
                  <ContentEditable
                    className={cn(
                      // 16px floor on mobile stops iOS Safari from auto-zooming the
                      // viewport on focus (it zooms any field under 16px and never
                      // zooms back out); drop to 14px from md up to match Input/Textarea
                      "min-h-20 px-3 py-2 text-base outline-none md:text-sm",
                      // reserve a left gutter for the block-drag handle so it never
                      // overlaps the text (the handle sits ~4px from the surface edge)
                      blockDragEnabled && "pl-7",
                      editorClassName,
                    )}
                    spellCheck
                  />
                }
                placeholder={
                  placeholder && isEmpty ? (
                    <div
                      className={cn(
                        "pointer-events-none absolute top-2 left-3 select-none text-muted-foreground",
                        // keep the placeholder aligned with the gutter-shifted text
                        blockDragEnabled && "left-7",
                      )}
                    >
                      {placeholder}
                    </div>
                  ) : null
                }
                ErrorBoundary={LexicalErrorBoundary}
              />
              <HistoryPlugin />
              <ListPlugin />
              {enableChecklist && <CheckListPlugin />}
              {/* Tab / Shift+Tab to indent + nest list items */}
              <TabIndentationPlugin />
              {/* markdown-style input: `- `, `1. `, `# `, `> `, `**bold**`, etc. */}
              <MarkdownShortcutPlugin transformers={MARKDOWN_TRANSFORMERS} />
              <LinkPlugin />
              {/* paste a URL over a selection to link it; Cmd/Ctrl+K to link */}
              <LinkShortcutsPlugin />
              {/* turn bare URLs / emails into links as they are typed or pasted */}
              <AutoLinkPlugin matchers={AUTO_LINK_MATCHERS} />
              {/* open links on click (new tab), in both read-only and edit mode;
                  drag-selecting a link's text suppresses navigation so it stays
                  editable. Without this, Lexical swallows the click for selection */}
              <ClickableLinkPlugin />
              {mentionItems?.length ? (
                <MentionTypeahead items={mentionItems} />
              ) : null}
              {issueReferenceItems?.length ? (
                <IssueReferenceTypeahead items={issueReferenceItems} />
              ) : null}
              {blockDragEnabled && anchorElem ? (
                <BlockDragPlugin anchorElem={anchorElem} />
              ) : null}
              {plugins}
              {/* image uploads, alt text, and width edits (and lifting loaded
                  buttons to blocks) merge into the previous undo step, so with
                  images or buttons on those updates must still report */}
              <OnChangePlugin
                onChange={handleChange}
                ignoreHistoryMergeTagChange={!images && !buttons}
              />
              <EditablePlugin editable={editable} />
              <EditorApiPlugin
                editorApi={editorApi}
                defaultContent={defaultContent}
              />
            </div>
          </RichTextButtons>
        </RichTextImages>
      </LexicalComposer>
    </div>
  );
};

// Matches a bare URL (scheme or `www.`) or email in a run of text. Combined
// into one pass so a generated anchor is never re-scanned (e.g. the address in
// `https://user@host` is not also matched as an email).
const LINKIFY_PATTERN =
  /(?:https?:\/\/|www\.)[^\s<]+|[^\s<@]+@[^\s<@]+\.[a-z]{2,}/gi;
// Trailing sentence punctuation that should sit outside the link, not in it.
const TRAILING_PUNCTUATION = /[.,!?;:)\]]+$/;

/**
 * Linkify bare URLs and email addresses in a rich-text HTML string so plain
 * links in stored content render as anchors. Splits on tags so matching only
 * happens in text (never inside attributes), and skips text already inside an
 * anchor so existing links are never double-wrapped.
 */
const linkifyBareUrls = (html: string): string => {
  let anchorDepth = 0;
  return html
    .split(/(<[^>]+>)/)
    .map((segment) => {
      if (segment.startsWith("<")) {
        if (/^<a[\s>]/i.test(segment)) anchorDepth++;
        else if (/^<\/a\s*>/i.test(segment) && anchorDepth > 0) anchorDepth--;
        return segment;
      }
      if (anchorDepth > 0) return segment;
      return segment.replace(LINKIFY_PATTERN, (match) => {
        const isEmail =
          match.includes("@") && !/^(https?:\/\/|www\.)/i.test(match);
        const trailing = isEmail
          ? ""
          : (TRAILING_PUNCTUATION.exec(match)?.[0] ?? "");
        const core = trailing ? match.slice(0, -trailing.length) : match;
        const href = isEmail
          ? `mailto:${core}`
          : core.startsWith("http")
            ? core
            : `https://${core}`;
        return `<a href="${href}">${core}</a>${trailing}`;
      });
    })
    .join("");
};

// Markdown inline link `[text](url)`, restricted to real link targets
// (http(s), mailto, or a root-relative path) so prose like `[label](note)` is
// left alone. DOMPurify is the backstop for the resulting href.
const MARKDOWN_LINK_PATTERN =
  /\[([^\]]+)\]\((https?:\/\/[^\s)]+|mailto:[^\s)]+|\/[^\s)]*)\)/g;

/**
 * Collapse markdown inline links `[text](url)` into anchors. The keystroke-only
 * MarkdownShortcutPlugin never converts links that are pasted (or otherwise not
 * typed character by character), so they reach storage as literal markdown;
 * this renders them as proper labeled links. Splits on tags so matching only
 * happens in text, and skips text already inside an anchor. Run before
 * {@link linkifyBareUrls} so the target becomes the href instead of being
 * re-linkified as bare text.
 */
const linkifyMarkdownLinks = (html: string): string => {
  let anchorDepth = 0;
  return html
    .split(/(<[^>]+>)/)
    .map((segment) => {
      if (segment.startsWith("<")) {
        if (/^<a[\s>]/i.test(segment)) anchorDepth++;
        else if (/^<\/a\s*>/i.test(segment) && anchorDepth > 0) anchorDepth--;
        return segment;
      }
      if (anchorDepth > 0) return segment;
      return segment.replace(
        MARKDOWN_LINK_PATTERN,
        (_match, text, url) => `<a href="${url}">${text}</a>`,
      );
    })
    .join("");
};

/**
 * Open external links in a new tab without leaking the opener. Relative links
 * (e.g. in-app issue references) are left to navigate in the same tab.
 */
const openLinksInNewTab = (node: Element): void => {
  const href = node.tagName === "A" ? node.getAttribute("href") : null;
  if (href && /^https?:\/\//i.test(href)) {
    node.setAttribute("target", "_blank");
    node.setAttribute("rel", "noopener noreferrer");
  }
};

// attributes an image keeps when images are allowed; everything else (class,
// style, srcset, event handlers) is stripped
const IMAGE_ATTRIBUTES = new Set(["src", "alt", "width"]);

/**
 * Reduce an `<img>` to an https `src` (normalized), `alt`, and a digits-only
 * `width`, or drop it when its source is not allowed. DOMPurify alone would
 * let `data:` sources, `class`, and `style` through. Image-only attributes are
 * removed from every other element.
 */
const sanitizeImage = (
  node: Element,
  allowInsecureHttp: boolean,
  isAllowedSrc?: (src: string) => boolean,
): void => {
  if (node.tagName !== "IMG") {
    for (const name of IMAGE_ATTRIBUTES) {
      if (name !== "alt") node.removeAttribute(name);
    }
    return;
  }
  const src = node.getAttribute("src");
  if (
    !src ||
    checkImageSrc(src, { allowInsecureHttp, isAllowedSrc }) !== "allowed"
  ) {
    node.remove();
    return;
  }
  for (const { name } of Array.from(node.attributes)) {
    if (!IMAGE_ATTRIBUTES.has(name)) node.removeAttribute(name);
  }
  node.setAttribute("src", new URL(src.trim()).href);
  const width = (node.getAttribute("width") ?? "").trim();
  if (!/^\d+$/.test(width) || Number(width) === 0) {
    node.removeAttribute("width");
  }
};

/**
 * Keep `data-variant` only as a button marker: on an `<a>`, with the value
 * `button`, and an `https://` or `mailto:` link. It is removed everywhere else
 */
const sanitizeButtonVariant = (node: Element): void => {
  if (!node.hasAttribute("data-variant")) return;
  const isButton =
    node.tagName === "A" &&
    node.getAttribute("data-variant") === "button" &&
    checkButtonHref(node.getAttribute("href")).ok;
  if (!isButton) node.removeAttribute("data-variant");
};

interface RichTextContentProps extends ComponentProps<"div"> {
  /** Stored HTML to render (sanitized before insertion). */
  html: string;
  /** Optional fallback when there is no content. */
  fallback?: ReactNode;
  /**
   * Render `<img>` tags (https sources only, with just `src`, `alt`, and a
   * pixel `width`). Off by default, so stored content cannot load remote images
   * (such as tracking pixels) unless the app opts in.
   */
  allowImages?: boolean;
  /** With `allowImages`, also render `http://` images. For local development only. */
  allowInsecureHttp?: boolean;
  /**
   * With `allowImages`, render only images whose source this accepts (e.g. a
   * host whitelist); others are dropped.
   */
  isAllowedSrc?: (src: string) => boolean;
}

/**
 * Render stored rich-text HTML, sanitized with DOMPurify to keep
 * user-generated content safe. Mirrors the editor's node-class theme.
 */
const RichTextContent = ({
  html,
  fallback = null,
  allowImages = false,
  allowInsecureHttp = false,
  isAllowedSrc,
  className,
  ...rest
}: RichTextContentProps) => {
  if (!html?.trim()) return <>{fallback}</>;

  // Collapse pasted markdown links first, then linkify any remaining bare
  // URLs/emails (incl. legacy plain-text content); add the hook around this
  // single synchronous sanitize so the new-tab behavior does not leak onto
  // other DOMPurify callers.
  DOMPurify.addHook("afterSanitizeAttributes", (node) => {
    openLinksInNewTab(node);
    sanitizeButtonVariant(node);
    if (allowImages) sanitizeImage(node, allowInsecureHttp, isAllowedSrc);
  });
  const clean = DOMPurify.sanitize(
    linkifyBareUrls(linkifyMarkdownLinks(html)),
    {
      ALLOWED_TAGS: [
        "p",
        "br",
        "b",
        "strong",
        "i",
        "em",
        "u",
        "s",
        "code",
        "pre",
        "ul",
        "ol",
        "li",
        "a",
        "h1",
        "h2",
        "h3",
        "h4",
        "h5",
        "h6",
        "blockquote",
        "span",
        ...(allowImages ? ["img"] : []),
      ],
      ALLOWED_ATTR: [
        "href",
        "target",
        "rel",
        "class",
        // a button marker, narrowed to `<a data-variant="button">` by
        // sanitizeButtonVariant
        "data-variant",
